  function clean(value) { return String(value || "").trim(); }
  function normalize(value) { return clean(value).toLowerCase().replace(/&/g, " and ").replace(/[^a-z0-9]+/g, " ").replace(/\s+/g, " ").trim(); }
  function parts(value) { return clean(value).split("|").map(clean).filter(Boolean); }
  function complicationParts(value, name) {
    const explicit = parts(value);
    const items = explicit.flatMap((item) => item.split(/,\s*/)).map((item) => clean(item).replace(/^and\s+/i, "")).filter(Boolean);
    return items.map((item) => item.split(/\s+/).length < 4 ? `${item} can complicate ${name}.` : item);
  }
  function titleOf(entry) { return clean(entry && (entry.name || entry.title || entry.displayName)); }
